import numpy as np
import matplotlib.pyplot as plt
from scipy import stats
from scipy.stats import beta
from sklearn.linear_model import LinearRegression
from sklearn.gaussian_process import GaussianProcessRegressor
from sklearn.gaussian_process.kernels import RBF, WhiteKernel
import warnings
warnings.filterwarnings('ignore')

# Set random seed for reproducibility
np.random.seed(42)

def create_experiment_design_plots():
    """Create plots showing different objectives of experiment design"""

    fig, axes = plt.subplots(2, 2, figsize=(15, 12))
    fig.suptitle('Different Objectives of Experiment Design', fontsize=16, fontweight='bold')

    x = np.linspace(0, 1, 301)

    # Plot 1: Approximate a rough function
    ax1 = axes[0, 0]
    y1 = np.sin(10 * np.pi * x) / (1 + 64 * (x - 0.5)**2)
    ax1.plot(x, y1, 'k-', linewidth=3, label='True function')

    # Uniform design points
    n = 15
    D = (np.arange(1, n+1) - 0.5) / n
    ax1.scatter(D, np.full(len(D), np.min(y1) - 0.05),
               color='blue', s=100, zorder=5)

    ax1.set_title('Approximate a Rough Function', fontsize=14, fontweight='bold')
    ax1.set_xlim(0, 1)
    ax1.set_ylim(np.min(y1) - 0.1, np.max(y1) + 0.05)
    ax1.set_xticks([])
    ax1.set_yticks([])

    # Plot 2: Approximate a smooth function
    ax2 = axes[0, 1]
    y2 = 1 / (1 + 64 * (x - 0.5)**2)
    ax2.plot(x, y2, 'k-', linewidth=3, label='True function')

    # Beta-distributed design points
    D2 = beta.ppf((np.arange(1, n+1) - 0.5) / n, 0.5, 0.5)
    ax2.scatter(D2, np.full(len(D2), np.min(y2) - 0.05),
               color='blue', s=100, zorder=5)

    ax2.set_title('Approximate a Smooth Function', fontsize=14, fontweight='bold')
    ax2.set_xlim(0, 1)
    ax2.set_ylim(np.min(y2) - 0.1, np.max(y2) + 0.05)
    ax2.set_xticks([])
    ax2.set_yticks([])

    # Plot 3: Optimization
    ax3 = axes[1, 0]
    y3 = 2/3 * beta.pdf(x, 2, 10) + 1/3 * beta.pdf(x, 10, 2)
    ax3.plot(x, y3, 'k-', linewidth=3, label='True function')

    # Combined design points
    n1 = int(n * 2/3)
    n2 = int(n / 3)
    D0 = (np.arange(1, n2+1) - 0.5) / n2
    D_beta = beta.ppf((np.arange(1, n1+1) - 0.5) / n1, 2, 10)
    D3 = np.concatenate([D0, D_beta])
    ax3.scatter(D3, np.full(len(D3), np.min(y3) - 0.05),
               color='blue', s=100, zorder=5)

    ax3.set_title('Optimization', fontsize=14, fontweight='bold')
    ax3.set_xlim(0, 1)
    ax3.set_ylim(np.min(y3) - 0.1, np.max(y3) + 0.05)
    ax3.set_xticks([])
    ax3.set_yticks([])

    # # Plot 4: Uncertainty propagation
