def create_regression_comparison():
    """Create comparison between Linear Regression and Gaussian Process Regression"""

    # Set up data
    np.random.seed(1)
    n = 10
    x = np.concatenate([np.zeros(n//2), np.ones(n//2)])

    # Define the true function
    def true_function(x):
        return np.sin(10 * np.pi * x) / (1 + 64 * (x - 0.25)**2) + x**2

    # Generate noisy observations
    y = true_function(x) + 0.1 * np.random.randn(n)

    # Test points
    test_x = np.linspace(-0.1, 1.1, 1000)
    true_y = true_function(test_x)

    fig, (ax1, ax2) = plt.subplots(1, 2, figsize=(15, 6))

    # Linear Regression
    ax1.set_title('Linear Regression', fontsize=16, fontweight='bold')
    ax1.plot(test_x, true_y, 'k-', linewidth=2, label='Truth')

    # Fit linear regression
    lr = LinearRegression()
    lr.fit(x.reshape(-1, 1), y)

    # Predictions
    pred_mean = lr.predict(test_x.reshape(-1, 1))

    # Calculate prediction intervals (simple approximation)
    residuals = y - lr.predict(x.reshape(-1, 1))
    mse = np.mean(residuals**2)
    # Prediction interval approximation
    pred_std = np.sqrt(mse + mse * (1/n + (test_x - np.mean(x))**2 / np.sum((x - np.mean(x))**2)))
    pred_lower = pred_mean - 2 * pred_std
    pred_upper = pred_mean + 2 * pred_std

    # Plot prediction interval
    ax1.fill_between(test_x, pred_lower, pred_upper,
                    color='pink', alpha=0.7, label='Prediction interval')
    ax1.plot(test_x, pred_mean, 'g--', linewidth=3, label='Prediction')
    ax1.scatter(x, y, color='blue', s=100, zorder=5)

    ax1.set_xlabel('x', fontsize=14)
    ax1.set_ylabel('y', fontsize=14)
    ax1.set_xlim(-0.1, 1.1)
    ax1.set_ylim(-0.5, 1.5)
    ax1.legend(fontsize=12)
    ax1.grid(True, alpha=0.3)

    # Gaussian Process Regression
    ax2.set_title('Gaussian Process Regression', fontsize=16, fontweight='bold')
    ax2.plot(test_x, true_y, 'k-', linewidth=2, label='Truth')

    # Fit Gaussian Process
    kernel = RBF(length_scale=1)
    gp = GaussianProcessRegressor(kernel=kernel, alpha=2e-2,
                                 n_restarts_optimizer=10)
    gp.fit(x.reshape(-1, 1), y)

    # Predictions
    gp_mean, gp_std = gp.predict(test_x.reshape(-1, 1), return_std=True)

    # Plot prediction interval
    ax2.fill_between(test_x, gp_mean - 2*gp_std, gp_mean + 2*gp_std,
                    color='pink', alpha=0.7, label='Prediction interval')
    ax2.plot(test_x, gp_mean, 'g--', linewidth=3, label='Prediction')
    ax2.scatter(x, y, color='blue', s=100, zorder=5)

    ax2.set_xlabel('x', fontsize=14)
    ax2.set_ylabel('y', fontsize=14)
    ax2.set_xlim(-0.1, 1.1)
    ax2.set_ylim(-0.5, 1.5)
    ax2.legend(fontsize=12)
    ax2.grid(True, alpha=0.3)

    plt.tight_layout()
    plt.show()

# Execute the functions
if __name__ == "__main__":
    print("Creating experiment design plots...")
    create_experiment_design_plots()

    print("Creating regression comparison plots...")
    create_regression_comparison()

    print("Visualization complete!")

